  // Exit: zoom toward camera (scale 1→2) while fading 1→0 — finishes exactly at COMP
  // Exit: spring-eased shrink, starts ~1 beat before the cut (SMOOTH = same ease as everything else)
  const buildExitSp    = sp(COMP - 6, { stiffness: 600, damping: 22 });
  const buildExitScale = Math.max(0, 1 - buildExitSp);
  const buildExitOp    = Math.max(0, 1 - buildExitSp);
  // Exit: scene 1/2 elements scale + fade out before the flash
  const exitSp    = sp(TRANS - 15, SMOOTH);
  const exitScale = Math.max(0, 1 - exitSp);
  // White flash: ramps up over 4 frames, holds 2, fades over 4
  const flashOpacity = interpolate(frame, [TRANS - 4, TRANS, TRANS + 2, TRANS + 6], [0, 1, 1, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });
  const wmSp    = sp(TRANS + 2);
  const s3IconA = sp(TRANS + 6);
  const s3IconB = sp(TRANS + 10);
  const s3IconC = sp(TRANS + 8);

  // Icons rotate slowly CW, then reverse CCW at B18≈324
  const S3_REVERSE = 341; // B19 — one beat later
  const ROT_SPEED  = 2.0; // degrees per frame
  const s3Rot = frame < TRANS
    ? 0
    : frame < S3_REVERSE
      ? (frame - TRANS) * ROT_SPEED
      : (S3_REVERSE - TRANS) * ROT_SPEED + (frame - S3_REVERSE) * -ROT_SPEED;

